create extension if not exists pgcrypto;
create table videos(id uuid primary key default gen_random_uuid(),youtube_video_id text unique not null,title text not null,description text,thumbnail_url text,video_url text not null,duration text,published_at timestamptz,is_available boolean not null default true,last_synced_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create index videos_published_idx on videos(published_at desc);
create index videos_title_idx on videos using gin(to_tsvector('simple',title));
create sequence request_seq start 10001;
create table requests(id uuid primary key default gen_random_uuid(),request_number text unique not null default ('KX-'||nextval('request_seq')),display_name text,status text not null default 'new' check(status in('new','reviewed','planned','completed')),admin_note text,idempotency_key text unique,created_at timestamptz default now(),updated_at timestamptz default now());
create index requests_created_idx on requests(created_at desc);
create table request_items(id uuid primary key default gen_random_uuid(),request_id uuid not null references requests(id) on delete cascade,video_id uuid not null references videos(id),created_at timestamptz default now(),unique(request_id,video_id));
create table notification_jobs(id uuid primary key default gen_random_uuid(),request_id uuid not null references requests(id) on delete cascade,channel text not null check(channel in('telegram','email','whatsapp')),status text not null default 'pending' check(status in('pending','processing','sent','failed','dead','skipped')),attempts int not null default 0,next_attempt_at timestamptz default now(),idempotency_key text unique not null,last_error text,created_at timestamptz default now(),updated_at timestamptz default now());
create index jobs_due_idx on notification_jobs(status,next_attempt_at);
create table notification_logs(id uuid primary key default gen_random_uuid(),request_id uuid not null references requests(id) on delete cascade,channel text not null,status text not null,attempts int default 1,provider_message_id text,last_error text,sent_at timestamptz,created_at timestamptz default now());
create table admin_users(id uuid primary key references auth.users(id) on delete cascade,email text unique not null,role text not null default 'admin' check(role in('owner','admin')),created_at timestamptz default now());
create table system_settings(id uuid primary key default gen_random_uuid(),key text unique not null,value jsonb,updated_at timestamptz default now());
alter table videos enable row level security;alter table requests enable row level security;alter table request_items enable row level security;
alter table notification_jobs enable row level security;alter table notification_logs enable row level security;alter table admin_users enable row level security;alter table system_settings enable row level security;
create function is_admin() returns boolean language sql stable security definer as $$select exists(select 1 from admin_users where id=auth.uid())$$;
create policy "public reads available videos" on videos for select using(is_available);
create policy "admin all videos" on videos for all using(is_admin());
create policy "admin all requests" on requests for all using(is_admin());
create policy "admin all items" on request_items for all using(is_admin());
create policy "admin all jobs" on notification_jobs for all using(is_admin());
create policy "admin all logs" on notification_logs for all using(is_admin());
create policy "admin reads self" on admin_users for select using(id=auth.uid());
create policy "admin all settings" on system_settings for all using(is_admin());
